from pathlib import Path
from openpyxl import load_workbook

path = Path("./data/order_summary.xlsx")
order_id = "ORD-6C71B1"

workbook = load_workbook(
    path,
    keep_vba=path.suffix.lower() == ".xlsm",
)

updated = []

for sheet in workbook.worksheets:
    headers = {
        str(cell.value).strip().lower(): cell.column
        for cell in sheet[1]
        if cell.value is not None
    }

    order_col = next(
        (headers[name] for name in ("order id", "order_id", "orderid", "order number")
         if name in headers),
        None,
    )
    status_col = next(
        (headers[name] for name in ("status", "order status", "order_status")
         if name in headers),
        None,
    )

    if order_col is None or status_col is None:
        continue

    for row in range(2, sheet.max_row + 1):
        current_id = str(sheet.cell(row, order_col).value or "").strip()
        current_status = str(sheet.cell(row, status_col).value or "").strip()

        if current_id == order_id and current_status.lower() == "cancelled":
            sheet.cell(row, status_col).value = "confirmed"
            updated.append(f"{sheet.title}!{sheet.cell(row, status_col).coordinate}")

if not updated:
    raise RuntimeError(
        f"No row found where order ID is {order_id!r} and status is 'cancelled'. "
        "The workbook was not saved."
    )

workbook.save(path)
print(f"Updated {order_id} to confirmed in: {', '.join(updated)}")

from openpyxl import load_workbook

path = "./data/order_summary.xlsx"
order_id = "ORD-6C71B1"

workbook = load_workbook(path)
updated = []

for sheet in workbook.worksheets:
    # Search each row for a header row containing both order ID and status columns.
    header_row = None
    order_col = None
    status_col = None

    for row in range(1, min(sheet.max_row, 20) + 1):
        headers = {
            str(sheet.cell(row, col).value).strip().lower(): col
            for col in range(1, sheet.max_column + 1)
            if sheet.cell(row, col).value is not None
        }

        order_col = next(
            (
                headers[name]
                for name in ("order id", "order_id", "orderid", "order number")
                if name in headers
            ),
            None,
        )
        status_col = next(
            (
                headers[name]
                for name in ("status", "order status", "order_status")
                if name in headers
            ),
            None,
        )

        if order_col is not None and status_col is not None:
            header_row = row
            break

    if header_row is None:
        continue

    for row in range(header_row + 1, sheet.max_row + 1):
        current_id = str(sheet.cell(row, order_col).value or "").strip()
        current_status = str(sheet.cell(row, status_col).value or "").strip()

        if current_id == order_id and current_status.lower() == "cancelled":
            status_cell = sheet.cell(row, status_col)
            status_cell.value = "confirmed"
            updated.append(f"{sheet.title}!{status_cell.coordinate}")

if not updated:
    raise RuntimeError(
        f"No row found where order ID is {order_id!r} and status is 'cancelled'. "
        "The workbook was not saved."
    )

workbook.save(path)
print(f"Updated {order_id} to confirmed in: {', '.join(updated)}")
